    if line==328: return ('Платформа · «Интерфейс»','личное','Моё → Качество (шапка Осмотра)',MODQ,1,'')
    if line==373: return ('Платформа · «Интерфейс»','личное','Моё → Уведомления',ALL,1,'')
    if line in (383,392,401,410): return ('Платформа · «Интерфейс»','личное','Моё → Качество (поведение Осмотра)',MODQ,1,'')
