    if 1087<=line<=1341: return ('Качество','личное','Моё → Качество',MODQ,1,'')
    if line==1361 or 1412<=line<=1532: return ('Качество · «Шаблоны отчётов (PDF)»','админ','Администрирование → Модули → Качество (шаблоны общие для компании; решение владельца 26.10.2026)',QM,1,'')
